-- ============================================================================
-- EVENT APP — Migration 29: web push notifications
-- ============================================================================
-- Devices subscribe per user. When a notification row is created, pg_net
-- calls the app's /api/push/dispatch endpoint (authenticated with a shared
-- secret kept in app.push_config), which sends the push with VAPID keys from
-- the same private table. Keys and secret are generated by the app on first
-- use and never leave the server or the database.

create table public.push_subscriptions (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references public.profiles (id) on delete cascade,
  endpoint text not null unique check (endpoint ~ '^https://' and char_length(endpoint) <= 1000),
  p256dh text not null check (char_length(p256dh) <= 200),
  auth text not null check (char_length(auth) <= 100),
  user_agent text,
  created_at timestamptz not null default now(),
  last_used_at timestamptz
);
create index push_subscriptions_user_idx on public.push_subscriptions (user_id);
alter table public.push_subscriptions enable row level security;
create policy push_subscriptions_select on public.push_subscriptions for select to authenticated using (user_id = (select auth.uid()));

create table app.push_config (
  id boolean primary key default true check (id),
  vapid_public text not null,
  vapid_private text not null,
  dispatch_secret text not null,
  app_url text not null,
  created_at timestamptz not null default now()
);
revoke all on app.push_config from public, anon, authenticated;

create or replace function public.save_push_subscription(p_endpoint text, p_p256dh text, p_auth text, p_user_agent text default null)
returns void
language plpgsql security definer set search_path = '' as $$
declare v_uid uuid := app.active_uid();
begin
  if v_uid is null then raise exception 'Sign in first' using errcode = '42501'; end if;
  insert into public.push_subscriptions (user_id, endpoint, p256dh, auth, user_agent)
  values (v_uid, p_endpoint, p_p256dh, p_auth, left(p_user_agent, 300))
  on conflict (endpoint) do update set user_id = excluded.user_id, p256dh = excluded.p256dh, auth = excluded.auth, user_agent = excluded.user_agent;
end $$;

create or replace function public.remove_push_subscription(p_endpoint text)
returns void
language plpgsql security definer set search_path = '' as $$
begin
  delete from public.push_subscriptions where endpoint = p_endpoint and user_id = app.active_uid();
end $$;

-- Service role: drop subscriptions the push service reports as gone (404/410).
create or replace function public.drop_push_subscription(p_endpoint text)
returns void
language sql security definer set search_path = '' as $$
  delete from public.push_subscriptions where endpoint = p_endpoint
$$;

-- Service role: read or create the push configuration.
create or replace function public.push_config_init(p_public text, p_private text, p_secret text, p_app_url text)
returns jsonb
language plpgsql security definer set search_path = '' as $$
begin
  insert into app.push_config (vapid_public, vapid_private, dispatch_secret, app_url) values (p_public, p_private, p_secret, p_app_url)
  on conflict (id) do update set app_url = excluded.app_url;
  return (select jsonb_build_object('vapid_public', vapid_public, 'vapid_private', vapid_private, 'dispatch_secret', dispatch_secret) from app.push_config);
end $$;

create or replace function public.push_config_get()
returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object('vapid_public', vapid_public, 'vapid_private', vapid_private, 'dispatch_secret', dispatch_secret, 'app_url', app_url)
  from app.push_config
$$;

-- Service role: what to send for a notification.
create or replace function public.push_payload(p_notification uuid)
returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object(
    'title', n.title, 'body', n.body, 'link', n.link,
    'subscriptions', coalesce((select jsonb_agg(jsonb_build_object('endpoint', s.endpoint, 'p256dh', s.p256dh, 'auth', s.auth))
                               from public.push_subscriptions s where s.user_id = n.user_id), '[]'::jsonb)
  )
  from public.notifications n where n.id = p_notification
$$;

-- On every notification, ask the app to deliver it (only if pg_net exists,
-- push is configured and the user has a device subscribed).
create or replace function app.notifications_push() returns trigger
language plpgsql security definer set search_path = '' as $$
declare c app.push_config;
begin
  if not exists (select 1 from pg_extension where extname = 'pg_net') then return null; end if;
  if not exists (select 1 from public.push_subscriptions s where s.user_id = new.user_id) then return null; end if;
  select * into c from app.push_config;
  if c.id is null then return null; end if;
  perform net.http_post(
    url := c.app_url || '/api/push/dispatch',
    body := jsonb_build_object('notification_id', new.id),
    headers := jsonb_build_object('content-type', 'application/json', 'x-push-secret', c.dispatch_secret),
    timeout_milliseconds := 5000
  );
  return null;
end $$;
create trigger notifications_push after insert on public.notifications for each row execute function app.notifications_push();

do $$
begin
  if exists (select 1 from pg_available_extensions where name = 'pg_net') then
    create extension if not exists pg_net with schema extensions;
  end if;
end $$;

do $$
declare f text;
begin
  foreach f in array array['public.save_push_subscription(text, text, text, text)', 'public.remove_push_subscription(text)'] loop
    execute format('revoke execute on function %s from public, anon', f);
    execute format('grant execute on function %s to authenticated, service_role', f);
  end loop;
  foreach f in array array['public.push_config_init(text, text, text, text)', 'public.push_config_get()', 'public.push_payload(uuid)', 'public.drop_push_subscription(text)'] loop
    execute format('revoke execute on function %s from public, anon, authenticated', f);
    execute format('grant execute on function %s to service_role', f);
  end loop;
end $$;
revoke execute on all functions in schema app from public, anon;
grant execute on all functions in schema app to authenticated, service_role;
